sable Azure Blob Storage management utility for Node.js and TypeScript.\",\r\n  \"main\": \"dist/index.js\",\r\n  \"types\": \"dist/index.d.ts\",\r\n  \"scripts\": {\r\n    \"build\": \"tsc -p tsconfig.json\",\r\n    \"start\": \"node dist/index.js\"\r\n  },\r\n  \"engines\": {\r\n    \"node\": \"\u003e=20.0.0\"\r\n  },\r\n  \"dependencies\": {\r\n    \"@azure/identity\": \"^4.12.0\",\r\n    \"@azure/logger\": \"^1.3.0\",\r\n    \"@azure/storage-blob\": \"^12.29.1\"\r\n  },\r\n  \"devDependencies\": {\r\n    \"@types/node\": \"^24.0.0\",\r\n    \"typescript\": \"^5.9.3\"\r\n  }\r\n}\r\n\n```\n\n### src\\blobStorageService.ts\n```\nimport { createReadStream } from \"node:fs\";\r\nimport { promises as fs } from \"node:fs\";\r\nimport {\r\n  BlobLeaseClient,\r\n  ContainerClient,\r\n} from \"@azure/storage-blob\";\r\n\r\nexport interface UploadBlobOptions {\r\n  metadata?: Record\u003cstring, string\u003e;\r\n  tags?: Record\u003cstring, string\u003e;\r\n  contentType?: string;\r\n}\r\n\r\nexport interface UploadBlobResult {\r\n  etag?: string;\r\n  requestId?: string;\r\n  versionId?: string;\r\n  leaseId?: string;\r\n}\r\n\r\nexport interface ListedBlob {\r\n  name: string;\r\n  contentLength?: number;\r\n  lastModified?: Date;\r\n}\r\n\r\nexport interface BlobStorageServiceOptions {\r\n  uploadBufferSizeBytes: number;\r\n  uploadConcurrency: number;\r\n  leaseDurationInSeconds: number;\r\n}\r\n\r\nexport class BlobStorageService {\r\n  constructor(\r\n    private readonly containerClient: ContainerClient,\r\n    private readonly options: BlobStorageServiceOptions,\r\n  ) {}\r\n\r\n  async uploadFile(\r\n    blobName: string,\r\n    filePath: string,\r\n    options: UploadBlobOptions = {},\r\n  ): Promise\u003cUploadBlobResult\u003e {\r\n    const blockBlobClient = this.containerClient.getBlockBlobClient(blobName);\r\n    const stats = await fs.stat(filePath);\r\n\r\n    if (!stats.isFile()) {\r\n      throw new Error(`Cannot upload ${filePath} because it is not a file.`);\r\n    }\r\n\r\n    let leaseClient: BlobLeaseClient | undefined;\r\n    let leaseId: string | undefined;\r\n\r\n    if (await blockBlobClient.exists()) {\r\n      leaseClient = blockBlobClient.getBlobLeaseClient();\r\n      const leaseResponse = await leaseClient.acquireLease(\r\n        this.options.leaseDurationInSeconds,\r\n      );\r\n      leaseId = leaseResponse.leaseId;\r\n    }\r\n\r\n    const fileStream = createReadStream(filePath);\r\n\r\n    try {\r\n      const uploadResponse = await blockBlobClient.uploadStream(\r\n        fileStream,\r\n        this.options.uploadBufferSizeBytes,\r\n        this.options.uploadConcurrency,\r\n        {\r\n          blobHTTPHeaders: options.contentType\r\n            ? { blobContentType: options.contentType }\r\n            : undefined,\r\n          metadata: options.metadata,\r\n          tags: options.tags,\r\n          conditions: leaseId ? { leaseId } : { ifNoneMatch: \"*\" },\r\n        },\r\n      );\r\n\r\n      return {\r\n        etag: uploadResponse.etag,\r\n        requestId: uploadResponse.requestId,\r\n        versionId: uploadResponse.versionId,\r\n        leaseId,\r\n      };\r\n    } finally {\r\n      fileStream.destroy();\r\n\r\n      if (leaseClient \u0026\u0026 leaseId) {\r\n        await leaseClient.releaseLease();\r\n      }\r\n    }\r\n  }\r\n\r\n  async downloadBlob(blobName: string): Promise\u003cBuffer\u003e {\r\n    const response = await this.containerClient\r\n      .getBlobClient(blobName)\r\n      .download();\r\n\r\n    if (!response.readableStreamBody) {\r\n      throw new Error(`Blob ${blobName} did not return a readable stream.`);\r\n    }\r\n\r\n    return streamToBuffer(response.readableStreamBody);\r\n  }\r\n\r\n  async listBlobs(): Promise\u003cListedBlob[]\u003e {\r\n    const blobs: ListedBlob[] = [];\r\n\r\n    for await (const blob of this.containerClient.listBlobsFlat()) {\r\n      blobs.push({\r\n        name: blob.name,\r\n        contentLength: blob.properties.contentLength,\r\n        lastModified: blob.properties.lastModified,\r\n      });\r\n    }\r\n\r\n    return blobs;\r\n  }\r\n\r\n  async deleteBlob(blobName: string): Promise\u003cboolean\u003e {\r\n    const response = await this.containerClient.deleteBlob(blobName, {\r\n      deleteSnapshots: \"include\",\r\n    });\r\n\r\n    return response._response.status === 202;\r\n  }\r\n}\r\n\r\nasync function streamToBuffer(\r\n  readableStream: NodeJS.ReadableStream,\r\n): Promise\u003cBuffer\u003e {\r\n  const chunks: Buffer[] = [];\r\n\r\n  for await (const chunk of readableStream) {\r\n    chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));\r\n  }\r\n\r\n  return Buffer.concat(chunks);\r\n}\r\n\n```\n\n### src\\config.ts\n```\nimport { ManagedIdentityCredential } from \"@azure/identity\";\r\nimport { AzureLogLevel, setLogLevel } from \"@azure/logger\";\r\nimport {\r\n  BlobServiceClient,\r\n  StorageRetryPolicyType,\r\n} from \"@azure/storage-blob\";\r\n\r\nconst DEFAULT_RETRY_MAX_TRIES = 5;\r\nconst DEFAULT_RETRY_DELAY_MS = 1_000;\r\nconst DEFAULT_RETRY_MAX_DELAY_MS = 8_000;\r\nconst DEFAULT_UPLOAD_BUFFER_SIZE_MB = 8;\r\nconst DEFAULT_UPLOAD_CONCURRENCY = 5;\r\nconst DEFAULT_LEASE_DURATION_SECONDS = 60;\r\n\r\nconst AZURE_LOG_LEVELS: AzureLogLevel[] = [\"verbose\", \"info\", \"warning\", \"error\"];\r\n\r\nexport interface BlobStorageConfig {\r\n  accountEndpoint: string;\r\n  containerName: string;\r\n  managedIdentityClientId?: string;\r\n  retryMaxTries: number;\r\n  retryDelayInMs: number;\r\n  retryMaxDelayInMs: number;\r\n  sdkLogLevel?: AzureLogLevel;\r\n  uploadBufferSizeBytes: number;\r\n  uploadConcurrency: number;\r\n  leaseDurationInSeconds: number;\r\n}\r\n\r\nexport function loadBlobStorageConfig(\r\n  env: NodeJS.ProcessEnv = process.env,\r\n): BlobStorageConfig {\r\n  const accountEndpoint = readRequiredEnv(env, \"AZURE_STORAGE_BLOB_ENDPOINT\");\r\n  const containerName = readRequiredEnv(env, \"AZURE_STORAGE_CONTAINER_NAME\");\r\n  const sdkLogLevel = parseLogLevel(env.AZURE_SDK_LOG_LEVEL);\r\n\r\n  return {\r\n    accountEndpoint,\r\n    containerName,\r\n    managedIdentityClientId: env.AZURE_CLIENT_ID,\r\n    retryMaxTries: parsePositiveInteger(\r\n      env.AZURE_STORAGE_RETRY_MAX_TRIES,\r\n      DEFAULT_RETRY_MAX_TRIES,\r\n      \"AZURE_STORAGE_RETRY_MAX_TRIES\",\r\n    ),\r\n    retryDelayInMs: parsePositiveInteger(\r\n      env.AZURE_STORAGE_RETRY_DELAY_MS,\r\n      DEFAULT_RETRY_DELAY_MS,\r\n      \"AZURE_STORAGE_RETRY_DELAY_MS\",\r\n    ),\r\n    retryMaxDelayInMs: parsePositiveInteger(\r\n      env.AZURE_STORAGE_RETRY_MAX_DELAY_MS,\r\n      DEFAULT_RETRY_MAX_DELAY_MS,\r\n      \"AZURE_STORAGE_RETRY_MAX_DELAY_MS\",\r\n    ),\r\n    sdkLogLevel,\r\n    uploadBufferSizeBytes:\r\n      parsePositiveInteger(\r\n        env.AZURE_STORAGE_UPLOAD_BUFFER_SIZE_MB,\r\n        DEFAULT_UPLOAD_BUFFER_SIZE_MB,\r\n        \"AZURE_STORAGE_UPLOAD_BUFFER_SIZE_MB\",\r\n      ) * 1024 * 1024,\r\n    uploadConcurrency: parsePositiveInteger(\r\n      env.AZURE_STORAGE_UPLOAD_MAX_CONCURRENCY,\r\n      DEFAULT_UPLOAD_CONCURRENCY,\r\n      \"AZURE_STORAGE_UPLOAD_MAX_CONCURRENCY\",\r\n    ),\r\n    leaseDurationInSeconds: parsePositiveInteger(\r\n      env.AZURE_STORAGE_LEASE_DURATION_SECONDS,\r\n      DEFAULT_LEASE_DURATION_SECONDS,\r\n      \"AZURE_STORAGE_LEASE_DURATION_SECONDS\",\r\n    ),\r\n  };\r\n}\r\n\r\nexport function createBlobServiceClient(\r\n  config: BlobStorageConfig,\r\n): BlobServiceClient {\r\n  if (config.sdkLogLevel) {\r\n    setLogLevel(config.sdkLogLevel);\r\n  }\r\n\r\n  const credential = config.managedIdentityClientId\r\n    ? new ManagedIdentityCredential(config.managedIdentityClientId)\r\n    : new ManagedIdentityCredential();\r\n\r\n  return new BlobServiceClient(config.accountEndpoint, credential, {\r\n    retryOptions: {\r\n      maxTries: config.retryMaxTries,\r\n      retryDelayInMs: config.retryDelayInMs,\r\n      maxRetryDelayInMs: config.retryMaxDelayInMs,\r\n      retryPolicyType: StorageRetryPolicyType.EXPONENTIAL,\r\n    },\r\n  });\r\n}\r\n\r\nfunction readRequiredEnv(env: NodeJS.ProcessEnv, key: string): string {\r\n  const value = env[key]?.trim();\r\n  if (!value) {\r\n    throw new Error(`Missing required environment variable ${key}.`);\r\n  }\r\n\r\n  return value;\r\n}\r\n\r\nfunction parsePositiveInteger(\r\n  rawValue: string | undefined,\r\n  fallback: number,\r\n  key: string,\r\n): number {\r\n  if (rawValue === undefined || rawValue.trim() === \"\") {\r\n    return fallback;\r\n  }\r\n\r\n  const parsed = Number.parseInt(rawValue, 10);\r\n  if (!Number.isInteger(parsed) || parsed \u003c= 0) {\r\n    throw new Error(`${key} must be a positive integer.`);\r\n  }\r\n\r\n  return parsed;\r\n}\r\n\r\nfunction parseLogLevel(rawValue: string | undefined): AzureLogLevel | undefined {\r\n  if (rawValue === undefined || rawValue.trim() === \"\") {\r\n    return undefined;\r\n  }\r\n\r\n  const normalized = rawValue.trim().toLowerCase();\r\n  if (AZURE_LOG_LEVELS.includes(normalized as AzureLogLevel)) {\r\n    return normalized as AzureLogLevel;\r\n  }\r\n\r\n  throw new Error(\r\n    `AZURE_SDK_LOG_LEVEL must be one of: ${AZURE_LOG_LEVELS.join(\", \")}.`,\r\n  );\r\n}\r\n\n```\n\n## Reference Answer\n\nNo reference answer provided.\n\n# Review Scoring Rubric\r\n\r\nYou are a senior Azure SDK code reviewer evaluating generated code.\r\n\r\n## General Criteria\r\n\r\nThese general quality criteria ALWAYS apply to every evaluation. You SHOULD actively verify these where possible (e.g., attempt to build the code, check package versions):\r\n\r\n1. **Code Builds** — Does the generated code compile/build without errors? If you have build tools available, attempt to build it.\r\n2. **Latest Package Versions** — Are the Azure SDK packages the latest stable versions? If you have version-check tools available, verify.\r\n3. **Best Practices** — Does it follow Azure SDK best practices? (DefaultAzureCredential, proper disposal, async patterns, etc.